import{_ as a,o as n,c as e,a6 as p}from"./chunks/framework.DfoD60a6.js";const u=JSON.parse('{"title":"IA-32 位址轉譯與 PAE","description":"","frontmatter":{"prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"theory/096-ia32.md","filePath":"theory/096-ia32.md"}'),i={name:"theory/096-ia32.md"};function l(t,s,r,c,d,b){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="ia-32-位址轉譯與-pae" tabindex="-1">IA-32 位址轉譯與 PAE <a class="header-anchor" href="#ia-32-位址轉譯與-pae" aria-label="Permalink to &quot;IA-32 位址轉譯與 PAE&quot;">​</a></h1><p>從 selector 和 offset 推到線性位址，再逐層計算非 PAE 與 PAE 分頁。對照 WUWAOS 的 RISC-V Sv39，兩者的頁表欄位各自獨立。</p><p>對照 WUWAOS 章節：<a href="./../spec/08-virtual-memory.html">08 · 頁面、虛擬記憶體與 COW</a></p><p>教材：恐龍書第 10 版 §9.6.1。 <a href="https://github.com/johnson931128/WUWAOS/blob/main/notes/9.6.md" target="_blank" rel="noreferrer">原始課堂筆記</a></p><p>IA-32 的位址轉譯可依序追蹤分段和分頁，再比較啟用 PAE 後的索引切法。</p><p>IA-32 的重點不是單純「logical address 直接 paging 成 physical address」，而是分成兩段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU 產生 logical address</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Segmentation unit</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>32-bit linear address</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Paging unit</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>physical address</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>physical memory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>也就是課本 Figure 9.21 的意思：<strong>segmentation unit 先把 logical address 轉成 linear address，paging unit 再把 linear address 轉成 physical address</strong>。課本也明確說 segmentation unit 和 paging unit 合起來，就等同於這個架構中的 MMU。</p><hr><h3 id="_1-ia-32-architecture-整體概念" tabindex="-1">1. IA-32 Architecture 整體概念 <a class="header-anchor" href="#_1-ia-32-architecture-整體概念" aria-label="Permalink to &quot;1. IA-32 Architecture 整體概念&quot;">​</a></h3><p><img src="https://hackmd.io/_uploads/HJLWIpQfMl.png" alt="IA-32 Architecture 整體概念插圖"> IA-32 是 Intel 32-bit 架構。它的記憶體管理分成兩個機制：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Segmentation</span></span>
<span class="line"><span>   負責：logical address → linear address</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. Paging</span></span>
<span class="line"><span>   負責：linear address → physical address</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>所以這裡會出現三種 address：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logical address：</span></span>
<span class="line"><span>CPU / 程式產生的位址，格式是 selector + offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>linear address：</span></span>
<span class="line"><span>segmentation 處理完後產生的 32-bit 位址</span></span>
<span class="line"><span></span></span>
<span class="line"><span>physical address：</span></span>
<span class="line"><span>paging 處理完後，真正送去 RAM 的位址</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>最容易混淆的就是 <strong>linear address 還不是 physical address</strong>。它只是 paging unit 的輸入。</p><hr><h3 id="_2-ia-32-segmentation-先處理-selector-offset" tabindex="-1">2. IA-32 Segmentation：先處理 selector + offset <a class="header-anchor" href="#_2-ia-32-segmentation-先處理-selector-offset" aria-label="Permalink to &quot;2. IA-32 Segmentation：先處理 selector + offset&quot;">​</a></h3><p><img src="https://hackmd.io/_uploads/BkPz8a7zzx.png" alt="IA-32 Segmentation：先處理 selector + offset插圖"> IA-32 的 logical address 長這樣：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logical address = (selector, offset)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其中：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selector = 16 bits</span></span>
<span class="line"><span>offset   = 32 bits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>selector 又被拆成三個部分：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>| s 13 bits | g 1 bit | p 2 bits |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>s</code> 是 segment number，也就是要查 descriptor table 的第幾個 segment descriptor。13 bits 可以表示：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2^13 = 8192 = 8K</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以一張 descriptor table 最多可以有 8K 個 segment entries。</p><p><code>g</code> 是用來決定查哪一張表。IA-32 有兩種 descriptor table：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LDT = Local Descriptor Table</span></span>
<span class="line"><span>     存放該 process 私有的 segment</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GDT = Global Descriptor Table</span></span>
<span class="line"><span>     存放所有 processes 共享的 segment</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>課本說 IA-32 每個 process 最多可以有 16K 個 segments，其中最多 8K 個 private segments 放在 LDT，最多 8K 個 shared segments 放在 GDT。每個 LDT / GDT entry 是 8-byte segment descriptor，裡面包含該 segment 的 base location 和 limit。</p><p><code>p</code> 跟 protection 有關，也就是權限檢查，例如目前執行狀態是否有資格存取這個 segment。</p><hr><h3 id="_3-segment-descriptor-到底存什麼" tabindex="-1">3. Segment descriptor 到底存什麼？ <a class="header-anchor" href="#_3-segment-descriptor-到底存什麼" aria-label="Permalink to &quot;3. Segment descriptor 到底存什麼？&quot;">​</a></h3><p>Segment descriptor 可以先理解成一筆「segment 的資料卡」。最重要的是兩個欄位：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base  = 這個 segment 的起始位置</span></span>
<span class="line"><span>limit = 這個 segment 的大小 / 邊界</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>segmentation unit 做的事就是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selector → 找到 segment descriptor</span></span>
<span class="line"><span>        → 取得 base 和 limit</span></span>
<span class="line"><span>        → 檢查 offset 有沒有超過 limit</span></span>
<span class="line"><span>        → 沒超過：linear address = base + offset</span></span>
<span class="line"><span>        → 超過：memory fault / trap</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>課本說 IA-32 的 linear address 是 32 bits。產生 linear address 前，硬體會先用 limit 檢查 address validity；如果不合法，會產生 memory fault 並 trap 到 OS；如果合法，才會把 offset 加到 base，得到 32-bit linear address。</p><hr><h3 id="_4-segmentation-例子" tabindex="-1">4. Segmentation 例子 <a class="header-anchor" href="#_4-segmentation-例子" aria-label="Permalink to &quot;4. Segmentation 例子&quot;">​</a></h3><p>假設某個 logical address 是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>selector = 指到某個 segment descriptor</span></span>
<span class="line"><span>offset   = 0x0000302A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>而 descriptor table 查到這個 segment descriptor：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>base  = 0x00400000</span></span>
<span class="line"><span>limit = 0x00100000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>先檢查 offset：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0x0000302A &lt; 0x00100000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>合法，所以：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear address = base + offset</span></span>
<span class="line"><span>               = 0x00400000 + 0x0000302A</span></span>
<span class="line"><span>               = 0x0040302A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>到這裡只完成第一段：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logical address → linear address</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>接下來才進入 paging。</p><hr><h3 id="_5-ia-32-paging-把-linear-address-轉-physical-address" tabindex="-1">5. IA-32 Paging：把 linear address 轉 physical address <a class="header-anchor" href="#_5-ia-32-paging-把-linear-address-轉-physical-address" aria-label="Permalink to &quot;5. IA-32 Paging：把 linear address 轉 physical address&quot;">​</a></h3><p><img src="https://hackmd.io/_uploads/H1NELTmffg.png" alt="IA-32 Paging：把 linear address 轉 physical address插圖"> IA-32 支援兩種 page size：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB page</span></span>
<span class="line"><span>4 MB page</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>先看標準的 <strong>4 KB page</strong>。</p><p>因為：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB = 4096 bytes = 2^12 bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以 page offset 需要 12 bits。</p><p>而 IA-32 linear address 是 32 bits，所以剩下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>32 - 12 = 20 bits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>這 20 bits 被拆成兩個 10 bits：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>32-bit linear address：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| p1 10 bits | p2 10 bits | d 12 bits |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>也就是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1：page directory index</span></span>
<span class="line"><span>p2：page table index</span></span>
<span class="line"><span>d ：page offset</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>課本說，IA-32 在 4-KB pages 下使用 two-level paging：高 10 bits 用來 reference page directory entry；CR3 register 指向目前 process 的 page directory；page directory entry 再指向 inner page table；中間 10 bits 用來 index page table；低 12 bits 是 4-KB page 內部 offset。</p><hr><h3 id="_6-p1、p2、entry-的關係" tabindex="-1">6. p1、p2、entry 的關係 <a class="header-anchor" href="#_6-p1、p2、entry-的關係" aria-label="Permalink to &quot;6. p1、p2、entry 的關係&quot;">​</a></h3><p>這裡要講清楚。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1 不是 entry</span></span>
<span class="line"><span>p1 是 index</span></span>
<span class="line"><span></span></span>
<span class="line"><span>p2 也不是 entry</span></span>
<span class="line"><span>p2 也是 index</span></span>
<span class="line"><span></span></span>
<span class="line"><span>entry 是表格裡面被 index 選到的那一格資料</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>一般 IA-32 的 page directory / page table 都是一張 4 KB 的表。每個 entry 是 32 bits，也就是 4 bytes。</p><p>所以一張表可以放：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4096 bytes / 4 bytes = 1024 entries</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1024 = 2^10</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以剛好需要 10 bits 來選其中一個 entry。</p><p>也就是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1 有 10 bits</span></span>
<span class="line"><span>→ 可以表示 0 ~ 1023</span></span>
<span class="line"><span>→ 用來選 page directory 裡的 1024 個 entries 其中一個</span></span>
<span class="line"><span></span></span>
<span class="line"><span>p2 有 10 bits</span></span>
<span class="line"><span>→ 可以表示 0 ~ 1023</span></span>
<span class="line"><span>→ 用來選 page table 裡的 1024 個 entries 其中一個</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>所以圖上的 <code>10 | 10 | 12</code> 其實是在說：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一個 10 bits：選 page directory 的一格</span></span>
<span class="line"><span>第二個 10 bits：選 page table 的一格</span></span>
<span class="line"><span>最後 12 bits：選 page 裡面的某個 byte</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h3 id="_7-4-kb-paging-完整流程" tabindex="-1">7. 4 KB paging 完整流程 <a class="header-anchor" href="#_7-4-kb-paging-完整流程" aria-label="Permalink to &quot;7. 4 KB paging 完整流程&quot;">​</a></h3><p>假設 segmentation 後得到：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linear address = 0x0040302A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>它被拆成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p1 = 1</span></span>
<span class="line"><span>p2 = 3</span></span>
<span class="line"><span>d  = 0x02A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>假設 CR3 指向目前 process 的 page directory。</p><p>流程如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Step 1:</span></span>
<span class="line"><span>用 p1 = 1 查 page directory[1]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page_directory[1]</span></span>
<span class="line"><span>→ 這個 entry 裡面記錄某張 page table 的位置</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 2:</span></span>
<span class="line"><span>用 p2 = 3 查那張 page table[3]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>page_table[3]</span></span>
<span class="line"><span>→ 這個 entry 裡面記錄某個 physical frame number</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Step 3:</span></span>
<span class="line"><span>用 d = 0x02A 當作 frame 內部 offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>physical address = physical frame base + d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>假設 <code>page_table[3]</code> 查到：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>physical frame number = 0x000AB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因為 page size 是 4 KB：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frame base = 0x000AB × 0x1000</span></span>
<span class="line"><span>           = 0x000AB000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>最後：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>physical address = 0x000AB000 + 0x02A</span></span>
<span class="line"><span>                 = 0x000AB02A</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>這就是 <code>linear address → physical address</code>。</p><hr><h3 id="_8-4-mb-page-跳過-page-table" tabindex="-1">8. 4 MB page：跳過 page table <a class="header-anchor" href="#_8-4-mb-page-跳過-page-table" aria-label="Permalink to &quot;8. 4 MB page：跳過 page table&quot;">​</a></h3><p>IA-32 也支援 4 MB page。這時候不用第二層 page table。</p><p>4 MB 是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 MB = 2^22 bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以 offset 需要 22 bits。</p><p>格式變成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>32-bit linear address：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| page directory 10 bits | offset 22 bits |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>如果 page directory entry 裡面的 <strong>Page Size flag</strong> 被設定，代表這個 entry 不是指向 page table，而是直接指向一個 4-MB page frame。課本說 Page Size flag 若被設定，page directory 會直接指向 4-MB page frame，跳過 inner page table，而 linear address 的低 22 bits 會作為 4-MB page frame 內部 offset。</p><p>所以：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB page：</span></span>
<span class="line"><span>CR3 → page directory → page table → 4-KB page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4 MB page：</span></span>
<span class="line"><span>CR3 → page directory → 4-MB page</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>好處是少查一層，TLB coverage 也比較大。缺點是 page 太大，容易浪費記憶體，也就是 internal fragmentation 可能比較嚴重。</p><hr><h3 id="_9-page-table-本身也可以被換到-disk" tabindex="-1">9. Page table 本身也可以被換到 disk <a class="header-anchor" href="#_9-page-table-本身也可以被換到-disk" aria-label="Permalink to &quot;9. Page table 本身也可以被換到 disk&quot;">​</a></h3><p>這段也很重要。IA-32 不只 data page 可以被 swap out，連 page table 本身也可以被 swap 到 disk。</p><p>原因是：每個 process 都可能有很大的 address space，如果每個 process 的所有 page tables 都常駐 RAM，會浪費很多 physical memory。</p><p>課本說 IA-32 page tables 可以被 swapped to disk；page directory entry 裡面可用 invalid bit 表示它指向的 table 在 memory 還是 disk。如果 table 在 disk，OS 可以用其他 31 bits 記錄 disk location，需要時再把 table 載回 memory。</p><p>所以可能發生兩種 fault：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>情況 A：</span></span>
<span class="line"><span>page table 在 RAM，但 data page 不在 RAM</span></span>
<span class="line"><span>→ page fault 後載入 data page</span></span>
<span class="line"><span></span></span>
<span class="line"><span>情況 B：</span></span>
<span class="line"><span>連 page table 本身都不在 RAM</span></span>
<span class="line"><span>→ 先把 page table 從 disk 載回來，再繼續查表</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h3 id="_10-pae-page-address-extension" tabindex="-1">10. PAE：Page Address Extension <a class="header-anchor" href="#_10-pae-page-address-extension" aria-label="Permalink to &quot;10. PAE：Page Address Extension&quot;">​</a></h3><p><img src="https://hackmd.io/_uploads/rkyPLT7MMl.png" alt="PAE：Page Address Extension插圖"> PAE 的目的：<strong>讓 32-bit processor 可以存取超過 4 GB 的 physical memory。</strong></p><p>傳統 IA-32 的限制是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>physical address = 32 bits</span></span>
<span class="line"><span>最大 physical memory = 2^32 bytes = 4 GB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>但後來程式與系統需要更多 RAM，所以 Intel 設計 PAE。課本說 PAE 讓 32-bit processors 可以 access physical address space larger than 4 GB，並且 paging 從 two-level scheme 變成 three-level scheme。</p><p>PAE 的位址切法是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>32-bit linear address：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>| 2 bits | 9 bits | 9 bits | 12 bits |</span></span>
<span class="line"><span>| PDPT   | PD      | PT      | offset  |</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>流程變成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CR3</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Page Directory Pointer Table</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Page Directory</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>Page Table</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>4-KB page</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>也就是 Figure 9.24 的圖。</p><hr><h3 id="_11-pae-為什麼是-2-9-9-12" tabindex="-1">11. PAE 為什麼是 2 + 9 + 9 + 12？ <a class="header-anchor" href="#_11-pae-為什麼是-2-9-9-12" aria-label="Permalink to &quot;11. PAE 為什麼是 2 + 9 + 9 + 12？&quot;">​</a></h3><p>先看最後的 12 bits：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB page = 2^12 bytes</span></span>
<span class="line"><span>所以 offset = 12 bits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>這個沒變。</p><p>PAE 中，page-directory entry 和 page-table entry 從 32 bits 變成 64 bits。課本明確說，PAE increased the page-directory and page-table entries from 32 to 64 bits。</p><p>一張 page directory / page table 還是 4 KB：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB = 4096 bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但每個 entry 變成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>64 bits = 8 bytes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以一張表只能放：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4096 / 8 = 512 entries</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>512 = 2^9</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以 page directory index 和 page table index 都變成 9 bits。</p><p>最上面的 PDPT 只有 4 個 entries：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 = 2^2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>所以最高位元用 2 bits 來選 PDPT entry。</p><p>因此 PAE 才是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2 + 9 + 9 + 12 = 32 bits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>注意：<strong>linear address 還是 32 bits，沒有變大。</strong></p><hr><h3 id="_12-pae-的索引位數與-36-位元實體位址" tabindex="-1">12. PAE 的索引位數與 36 位元實體位址 <a class="header-anchor" href="#_12-pae-的索引位數與-36-位元實體位址" aria-label="Permalink to &quot;12. PAE 的索引位數與 36 位元實體位址&quot;">​</a></h3><p>這邊前面卡住的地方，因果要正確。</p><p>PAE 不是先天「因為 36 所以 24」。正確順序是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PAE 把 PDE/PTE 從 32 bits 擴成 64 bits</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>entry 裡面可以放更長的 physical frame base address</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>課本說 base address of page tables and page frames 從 20 bits 擴成 24 bits</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4 KB page 的 offset 固定是 12 bits</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>physical address = 24-bit frame base/index 部分 + 12-bit offset</span></span>
<span class="line"><span>                 = 36 bits</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>課本原文的邏輯就是：PAE 將 page-directory / page-table entries 從 32 bits 增加到 64 bits，這讓 page tables 與 page frames 的 base address 從 20 bits 延伸到 24 bits；再配合 12-bit offset，IA-32 的 address space 增加到 36 bits，可支援最多 64 GB physical memory。</p><p>所以這裡要記：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24 bits：</span></span>
<span class="line"><span>來自 PAE entry 格式可以記錄更長的 page frame base address</span></span>
<span class="line"><span></span></span>
<span class="line"><span>36 bits：</span></span>
<span class="line"><span>24-bit frame/base 部分 + 12-bit offset 的結果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>PAE 的重點不是讓 process 看到更大的 virtual address。單一 32-bit process 的 linear address 仍是 32 bits，也就是最多 4 GB virtual address space。PAE 擴大的是 <strong>physical address ability</strong>，也就是整台機器能用更多 RAM。</p><hr><h3 id="_13-9-6-1-最終總結" tabindex="-1">13. 9.6.1 最終總結 <a class="header-anchor" href="#_13-9-6-1-最終總結" aria-label="Permalink to &quot;13. 9.6.1 最終總結&quot;">​</a></h3><p>IA-32 位址轉換整體如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logical address = selector + offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>selector</span></span>
<span class="line"><span>→ 決定查 LDT 或 GDT</span></span>
<span class="line"><span>→ 找到 segment descriptor</span></span>
<span class="line"><span>→ descriptor 裡有 base 和 limit</span></span>
<span class="line"><span>→ 檢查 offset 是否超過 limit</span></span>
<span class="line"><span>→ 合法則 linear address = base + offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>linear address</span></span>
<span class="line"><span>→ 交給 paging unit</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4 KB paging：</span></span>
<span class="line"><span>linear address = p1 + p2 + d</span></span>
<span class="line"><span>p1 查 page directory</span></span>
<span class="line"><span>p2 查 page table</span></span>
<span class="line"><span>d 是 4-KB page 內 offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>4 MB paging：</span></span>
<span class="line"><span>page directory entry 直接指向 4-MB page</span></span>
<span class="line"><span>低 22 bits 當 offset</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PAE：</span></span>
<span class="line"><span>linear address 仍然 32 bits</span></span>
<span class="line"><span>切成 2 + 9 + 9 + 12</span></span>
<span class="line"><span>多一層 page directory pointer table</span></span>
<span class="line"><span>PDE/PTE 從 32 bits 變 64 bits</span></span>
<span class="line"><span>frame/base address 欄位從 20 bits 擴成 24 bits</span></span>
<span class="line"><span>physical address 變成 36 bits</span></span>
<span class="line"><span>最多支援 64 GB physical memory</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br></div></div><p>最核心的一句話是：</p><p><strong>IA-32 的記憶體管理是「先 segmentation，後 paging」。Segmentation 負責把 <code>(selector, offset)</code> 變成 32-bit linear address；paging 再把這個 linear address 變成真正的 physical address。PAE 則是在 paging 架構中加一層表，並把 entries 變大，讓 32-bit 系統可以指到超過 4 GB 的實體記憶體。</strong></p>`,161)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
